//源表：robot_names.xlsx（预设名称表）
#pragma warning disable 8981

using System.Collections.Generic;
using System.IO;

namespace Ros.Config
{
    public partial class ConfigManager
    {
        public Dictionary<int, robot_names> robot_namesData;
        public robot_names Getrobot_namesConfig(int key)
        {
            return ConfigBinary.Require(robot_namesData, key, "robot_names");
        }
        private void Loadrobot_namesConfig()
        {
            using (BinaryReader r = ConfigBinary.Open("robot_names"))
            {
                int count = r.ReadInt32();
                robot_namesData = new Dictionary<int, robot_names>(count);
                for (int i = 0; i < count; i++)
                {
                    robot_names row;
                    row.key = r.ReadInt32();
                    row.name = ConfigBinary.ReadString(r);
                    robot_namesData.Add(row.key, row);
                }
            }
        }
    }
    public struct robot_names
    {
        public int key;  // 主键
        public string name;  // 名称
    }
}
